$ErrorActionPreference='Stop'
$effective=Import-Csv reports/phase2/effective_files.csv
$latest=@{};foreach($e in $effective){$latest[$e.Path]=$e}
$lists=@{};foreach($l in Import-Csv reports/lists.csv){$rel=$l.File.Replace('\','/');$cut=$rel.IndexOf('/');$path=$rel.Substring($cut+1);if($latest.ContainsKey($path) -and $latest[$path].Pak -eq $rel.Substring(0,$cut)){$lists[$path]=$l}}
$motions=@{};foreach($m in Import-Csv reports/motions.csv){$rel=$m.File.Replace('\','/');$cut=$rel.IndexOf('/');$path=$rel.Substring($cut+1);if($latest.ContainsKey($path) -and $latest[$path].Pak -eq $rel.Substring(0,$cut)){if(!$motions.ContainsKey($path)){$motions[$path]=@{}};$motions[$path]["$($m.ID):$($m.Switch)"]=$m}}
function Resolve-Motion($path,$key,$depth=0){if($depth -gt 16){throw 'inheritance cycle'};if(!$motions.ContainsKey($path)){return $null};$m=$motions[$path][$key];if($m -and $m.Kind -ne 'empty'){return [pscustomobject]@{Origin=$path;Motion=$m;Depth=$depth}};$base=$lists[$path].Base;if($base){return Resolve-Motion ('natives/stm/'+$base.ToLower()+'.1047') $key ($depth+1)};return $null}
$result=foreach($path in $lists.Keys | Sort-Object){if($path -notmatch 'handgun00|handgun01|general[hm]'){continue};foreach($key in $motions[$path].Keys | Sort-Object){$r=Resolve-Motion $path $key;$m=$motions[$path][$key];[pscustomobject]@{List=[IO.Path]::GetFileName($path);ID=$m.ID;Switch=$m.Switch;LocalKind=$m.Kind;ResolvedKind=if($r){$r.Motion.Kind}else{'unresolved'};Name=if($r){$r.Motion.Name}else{''};Origin=if($r){$r.Origin}else{''};Depth=if($r){$r.Depth}else{''};Frames=if($r){$r.Motion.Frames}else{''};FPS=if($r){$r.Motion.FPS}else{''};Tracks=if($r){$r.Motion.BoneTracks}else{''};Mask=$m.Mask}}}
$result | Export-Csv reports/phase2/handgun_resolved.csv -NoTypeInformation -Encoding utf8
$result | Group-Object List | ForEach-Object {[pscustomobject]@{List=$_.Name;Slots=$_.Count;Local=@($_.Group | Where-Object LocalKind -ne empty).Count;Inherited=@($_.Group | Where-Object Depth -gt 0).Count;Unresolved=@($_.Group | Where-Object ResolvedKind -eq unresolved).Count}} | Export-Csv reports/phase2/handgun_resolution_summary.csv -NoTypeInformation
$result | Where-Object {$_.List -eq 'ch0100_handgun00h_add.motlist.1047'} | Select-Object -First 20 ID,Name,Mask,Frames,Tracks | ConvertTo-Json
